async function tipInvisibleExplicitSound({ name, sound, peaceful = false, tame = 0,
    gold = 0, seed = null, rngLog = false, role = '', inventory = [], data = {}, extra = {},
    moves = null, traps = null, endgame = false, race = '', hallucinating = false,
    polyself = null, bystanders = [], moonphase = null, datetime = null, night = null,
    hour = null, heroFemale = null, town = false, allowFallback = false, setup = null } = {}) {
    installStableNonShopFloorState();
    if (town) game.level.flags.has_town = true;
    if (seed != null) initRng(seed);
    if (rngLog) enableRngLog({ reset: true });
    if (heroFemale != null) {
        game.flags.female = !!heroFemale;
        game.u.female = !!heroFemale;
    }
    if (moves != null) {
        game.moves = moves;
        game.context ??= {};
        game.context.moves = moves;
    }
    if (race) {
        game._startup_race = race;
        game.urace = { ...(game.urace || {}), noun: race, adj: race === 'orc' ? 'orcish' : race };
    }
    if (role) {
        game._startup_role = role;
        game.urole = { ...(game.urole || {}), name: { m: role, f: role } };
    }
    if (hallucinating) {
        game.u.hallucinating = true;
        game.u._statusSuffix = ' Hallu';
    }
    if (moonphase != null) game.flags.moonphase = moonphase;
    if (datetime != null) game._datetime = datetime;
    if (night != null) game.flags.night = night;
    if (hour != null) game.flags.hour = hour;
    if (polyself) {
        game.u._polyself_form = typeof polyself === 'string' ? { name: polyself } : polyself;
    }
    if (endgame) {
        game.astral_level = { dnum: 8, dlevel: 5 };
        game.u.uz = { dnum: 8, dlevel: 1 };
    }
    game.u.seeInvisible = false;
    const targetLoc = game.level.at(6, 5);
    const helmet = wornArmor(3063556, 'orcish helm', 'h');
    const target = ordinaryThrowTarget(name, 6, 5, {
        minvis: 1,
        perminvis: 1,
        msleeping: 0,
        mcanmove: true,
        mcansee: true,
        mpeaceful: peaceful,
        mtame: tame,
        mstrategy: 'waitforu',
        data: { name, mlevel: 1, mlet: '@', humanoid: true, msound: sound, ...data },
        ...extra,
    });
    game.inventory = [helmet, ...inventory];
    if (gold) {
        game.inventory.push(goldPieces(3063557, gold));
        game._goldCount = gold;
    }
    game.level.monsters = [target, ...bystanders];
    if (traps) game.level.traps = traps;
    if (setup) setup({ target, targetLoc, helmet });
    markSquareVisible(6, 5);

    await enterTipCommand();
    await rhack('h');
    await rhack('l');

    assert.equal(game._command_mode, null);
    assert.equal(game.context.move, 1);
    assert.equal(target.mstrategy, 0);
    assert.equal(targetLoc.map_invisible, true);
    assert.match(game._pending_message, /You briefly doff your helm\./);
    const unexpected = allowFallback
        ? /doesn't respond|waves|tips .* in response|gestures|unseen creature/
        : /doesn't respond|Nothing happens|waves|tips .* in response|gestures|unseen creature/;
    assert.doesNotMatch(game._pending_message, unexpected);
    return { target, targetLoc, message: game._pending_message };
}

function installTipPriestTemple(target, { shrineAlign = A_LAWFUL, heroAlign = A_LAWFUL, record = 0 } = {}) {
    game.u.ualign = { ...(game.u.ualign || {}), type: heroAlign, record };
    game.level.rooms = [{ rtype: TEMPLE, roomnoidx: 0 }];
    const priestLoc = game.level.at(target.mx, target.my);
    priestLoc.roomno = ROOMOFFSET;
    priestLoc.typ = ROOM;
    const altarLoc = game.level.at(target.mx, target.my + 1);
    altarLoc.roomno = ROOMOFFSET;
    altarLoc.typ = ALTAR;
    altarLoc.flags = Align2amask(shrineAlign) | AM_SHRINE;
    altarLoc.altarmask = altarLoc.flags;
    target.ispriest = 1;
    target.shrine = {
        room: ROOMOFFSET,
        align: shrineAlign,
        x: target.mx,
        y: target.my + 1,
    };
}

