    assert.equal(landing.shipObject.handled, false);
    assert.equal(landing.floorEffects.consumed, true);
    assert.equal(queuedImpactDropsFor().length, 0);
    assert.equal(game.level.objects.some(obj => obj.id === boulder.id), false);
