        game.level.monsters = [goblin];
        enableRngLog({ reset: true });

        await rhack('t');
        await rhack('h');
        prepare(goblin);
        await rhack('l');

        const message = game._pending_message || '';
        assert.match(message, /^Crash!$/, name);
